/* Yellow Fox 100 by pablofernz — https://uiverse.io/pablofernz/yellow-fox-100 */
.formContainer {
  height: 100%;

  width: 300px;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column-reverse;

  gap: 10px;
  position: relative;
}

.formContainer > label {
  font-family: Basier Square;
  font-weight: 900;
  font-size: 15px;
  color: rgb(99, 99, 99);
  text-align: start;
  align-self: flex-start;
  transition: all 0.3s ease;
}

.formContainer > input {
  width: 100%;
  height: 40px;
  border-radius: 10px;
  font-weight: 900px;
  background-color: transparent;
  color: rgb(99, 99, 99);
  border: 2px solid rgb(85, 85, 85);
  font-size: 15px;
  font-family: Basier Square;
  padding-left: 10px;
  transition: all 0.3s ease;
  z-index: 5;
}

.formContainer > input:focus {
  color: rgb(197, 197, 197);
  outline: none;
  border: 2px solid rgb(255, 255, 255);
  box-shadow:
    0px 0px 10px rgba(255, 255, 255, 0.145),
    0px 0px 5px rgba(255, 255, 255, 0.145) inset;
}

.formContainer > input:focus + label {
  color: rgb(197, 197, 197);
  text-shadow: 0px 0px 10px rgba(255, 255, 255, 0.145);
}

.formContainer > input::placeholder {
  color: rgb(85, 85, 85);
  transition: all 0.5s ease;
}

.formContainer > input:focus::placeholder {
  color: rgb(150, 150, 150);
}
